insert into public.brand_size_charts
  (brand_key, brand_label, brand_match, department, garment, category_match, rows, note, source_url, confidence, verified, updated_by) values
  ('cotopaxi', 'Cotopaxi', ARRAY['cotopaxi']::text[], 'Men', 'Apparel (US alpha, body inches)', ARRAY['jacket','fleece','vest','top','shirt','windbreaker','fuego','teca','down','shell','bottom','pant','trouser','short','jogger']::text[], $json$[{"size":"S","measurements":{"chest":"34-36.5","waist":"27-29.5","hip":"33-36","sleeve":"32-32.5","inseam":"32"}},{"size":"M","measurements":{"chest":"37-40","waist":"30-33","hip":"36.5-39.5","sleeve":"33-33.5","inseam":"32"}},{"size":"L","measurements":{"chest":"41-43.5","waist":"34-36.5","hip":"40-43","sleeve":"33.5-34","inseam":"32"}},{"size":"XL","measurements":{"chest":"44-47","waist":"37-40.5","hip":"44-46.5","sleeve":"34.5-35","inseam":"32"}},{"size":"XXL","measurements":{"chest":"48-50.5","waist":"41-45.5","hip":"47-50","sleeve":"35-35.5","inseam":"32"}}]$json$::jsonb, 'US-3287 REPLACED the approximation that stood here with Cotopaxi''s OWN published numbers, which is also why bottoms now resolve: the brand publishes ONE chart per department covering everything it makes, hip and inseam included. Sourced from the UK site — cotopaxi.com''s /pages/sizing-charts redirects to the homepage and its /pages/sizing-information 404s, and uk.cotopaxi.com is the working copy of the same guide. ⚠ THE DEL DÍA colour blocking is ONE-OF-A-KIND (remnant fabric, the sewer picks the colours) — a wild colour block is the PRODUCT, not a flaw. On the Fuego down jacket the FILL LOFT is the grade (a flat or leaking baffle is a defect).', 'https://uk.cotopaxi.com/pages/sizing-information', 0.85, false, 'migration:00781'),
  ('cotopaxi', 'Cotopaxi', ARRAY['cotopaxi']::text[], 'Women', 'Apparel (US alpha, body inches)', ARRAY['jacket','fleece','vest','top','shirt','windbreaker','fuego','teca','down','shell','bottom','pant','trouser','short','legging','jogger']::text[], $json$[{"size":"XS","measurements":{"bust":"32-33.5","waist":"25-26.5","hip":"34-35.5","sleeve":"29.75-30","inseam":"30.5"}},{"size":"S","measurements":{"bust":"34-35.5","waist":"27-28.5","hip":"36-37.5","sleeve":"30.25-30.75","inseam":"30.5"}},{"size":"M","measurements":{"bust":"36-37.5","waist":"29-31","hip":"38-39.75","sleeve":"31-31.25","inseam":"30.5"}},{"size":"L","measurements":{"bust":"38-40.5","waist":"31.5-33.5","hip":"40-42.75","sleeve":"31.5-32","inseam":"30.5"}},{"size":"XL","measurements":{"bust":"41-43.5","waist":"34-36.5","hip":"43-45.5","sleeve":"32.25-32.75","inseam":"30.5"}}]$json$::jsonb, 'US-3287 REPLACED the approximation that stood here with Cotopaxi''s OWN published numbers, which is also why bottoms now resolve. Sourced from the UK site; see the men''s chart for why. The women''s run stops at XL — Cotopaxi sells extended sizing under its own collection and publishes no chart for it. ⚠ THE DEL DÍA colour blocking is ONE-OF-A-KIND (remnant fabric) — a wild colour block is the PRODUCT. On the Fuego the FILL LOFT is the grade.', 'https://uk.cotopaxi.com/pages/sizing-information', 0.85, false, 'migration:00781'),
  ('7forallmankind', '7 For All Mankind', ARRAY['7 for all mankind','7forallmankind','seven for all mankind','7fam']::text[], 'Women', 'Tops, jackets & dresses (alpha, body inches)', ARRAY['top','tee','shirt','blouse','sweater','knit','hoodie','sweatshirt','tank','jacket','coat','outerwear','blazer','vest','dress','romper','jumpsuit']::text[], $json$[{"size":"XXS","measurements":{"bust":"31.875","waist":"23","hip":"33"}},{"size":"XS","measurements":{"bust":"32.625-33.5","waist":"24-25","hip":"34-35"}},{"size":"S","measurements":{"bust":"34.25-35","waist":"26-27","hip":"36-37"}},{"size":"M","measurements":{"bust":"36.25-37.375","waist":"28-29","hip":"38-39"}},{"size":"L","measurements":{"bust":"38.625-39.75","waist":"30-31","hip":"40-41"}},{"size":"XL","measurements":{"bust":"41-42.125","waist":"31.875-32.875","hip":"42-43"}},{"size":"XXL","measurements":{"bust":"43.25-44.5","waist":"33.875-35.875","hip":"43.875-45.75"}}]$json$::jsonb, '7FAM publishes ONE women''s body chart and applies it to tops, jackets and dresses alike. Body measurements, not flat. The brand prints centimetres first; these are its own inch column with the eighths written as decimals.', 'https://7forallmankind.com/pages/size-chart', 0.85, false, 'migration:00781'),
  ('agjeans', 'AG Jeans', ARRAY['ag jeans','agjeans','adriano goldschmied']::text[], 'Women', 'Tops, jackets & dresses (alpha, body inches)', ARRAY['top','tee','shirt','blouse','sweater','knit','hoodie','sweatshirt','tank','jacket','coat','outerwear','blazer','vest','dress','romper','jumpsuit']::text[], $json$[{"size":"XXS / 00","measurements":{"bust":"30","waist":"23","hip":"33"}},{"size":"XS / 0","measurements":{"bust":"31-32","waist":"24-25","hip":"34-35"}},{"size":"S / 4","measurements":{"bust":"33-34","waist":"26-27","hip":"36-37"}},{"size":"M / 6","measurements":{"bust":"35-36","waist":"28-29","hip":"38-39"}},{"size":"L / 10","measurements":{"bust":"37-38.5","waist":"30-31","hip":"40-41.5"}},{"size":"XL / 14","measurements":{"bust":"39.5-41","waist":"32-33","hip":"42.5-44"}},{"size":"XXL / 18","measurements":{"bust":"42-43.5","waist":"34","hip":"45-46.5"}}]$json$::jsonb, 'AG publishes one women''s body chart keyed on denim waist, with alpha and US numeric alongside. The alpha rows are here; the denim-waist rows are on AG''s jeans chart. Body measurements, not flat.', 'https://www.agjeans.com/pages/womens-size-guide', 0.85, false, 'migration:00781'),
  ('agjeans', 'AG Jeans', ARRAY['ag jeans','agjeans','adriano goldschmied']::text[], 'Men', 'Tops & outerwear (alpha, body inches)', ARRAY['top','tee','shirt','polo','sweater','knit','hoodie','sweatshirt','jacket','coat','outerwear','blazer','vest']::text[], $json$[{"size":"XS","measurements":{"chest":"35.5-36.5","waist":"28-29","hip":"34.5-35.5"}},{"size":"S","measurements":{"chest":"37.5-38.5","waist":"30-31","hip":"36.5-37.5"}},{"size":"M","measurements":{"chest":"39.5-40.5","waist":"32-33","hip":"38.5-39.5"}},{"size":"L","measurements":{"chest":"41.5-42.5","waist":"34-36","hip":"40.5-42.5"}},{"size":"XL","measurements":{"chest":"43.5-44.5","waist":"38-40","hip":"44.5-46.5"}},{"size":"XXL","measurements":{"chest":"46.5-48","waist":"42-44","hip":"48-49.5"}}]$json$::jsonb, 'AG publishes one men''s body chart keyed on denim waist (28-44), with the alpha and chest columns beside it. Body measurements, not flat.', 'https://www.agjeans.com/pages/mens-size-guide', 0.85, false, 'migration:00781'),
  ('americaneagle', 'American Eagle', ARRAY['american eagle','americaneagle','aerie']::text[], 'Women', 'Tops & outerwear (alpha/numeric, body inches)', ARRAY['top','tee','shirt','blouse','sweater','knit','hoodie','sweatshirt','tank','jacket','coat','outerwear','blazer','vest']::text[], $json$[{"size":"XXS / 00","measurements":{"bust":"31"}},{"size":"XS / 0","measurements":{"bust":"32"}},{"size":"XS / 2","measurements":{"bust":"33"}},{"size":"S / 4","measurements":{"bust":"34"}},{"size":"S / 6","measurements":{"bust":"35"}},{"size":"M / 8","measurements":{"bust":"36"}},{"size":"M / 10","measurements":{"bust":"37.5"}},{"size":"L / 12","measurements":{"bust":"39"}},{"size":"L / 14","measurements":{"bust":"40.5"}},{"size":"XL / 16","measurements":{"bust":"42"}},{"size":"XXL / 18","measurements":{"bust":"44"}}]$json$::jsonb, 'AE''s women''s tops chart carries BUST ONLY, and AE publishes no separate outerwear chart — its jackets are sized off this one. Body measurements.', 'https://www.ae.com/us/en/content/help/women-size-chart', 0.85, false, 'migration:00781'),
  ('americaneagle', 'American Eagle', ARRAY['american eagle','americaneagle','aerie']::text[], 'Women', 'Dresses & skirts (alpha/numeric, body inches)', ARRAY['dress','skirt','romper','jumpsuit']::text[], $json$[{"size":"XXS / 00","measurements":{"bust":"31","waist":"23.5","hip":"33"}},{"size":"XS / 0","measurements":{"bust":"32","waist":"24.5","hip":"34"}},{"size":"XS / 2","measurements":{"bust":"33","waist":"25.5","hip":"35"}},{"size":"S / 4","measurements":{"bust":"34","waist":"26.5","hip":"36"}},{"size":"S / 6","measurements":{"bust":"35","waist":"27.5","hip":"37"}},{"size":"M / 8","measurements":{"bust":"36","waist":"28.5","hip":"38"}},{"size":"M / 10","measurements":{"bust":"37.5","waist":"30","hip":"39.5"}},{"size":"L / 12","measurements":{"bust":"39","waist":"31.5","hip":"41"}},{"size":"L / 14","measurements":{"bust":"40.5","waist":"33","hip":"42.5"}},{"size":"XL / 16","measurements":{"bust":"42","waist":"34.5","hip":"44"}},{"size":"XXL / 18","measurements":{"bust":"44","waist":"36.5","hip":"46"}}]$json$::jsonb, 'AE''s dresses-and-skirts chart. Body measurements, not flat.', 'https://www.ae.com/us/en/content/help/women-size-chart', 0.85, false, 'migration:00781'),
  ('americaneagle', 'American Eagle', ARRAY['american eagle','americaneagle','aerie']::text[], 'Men', 'Tops & outerwear (alpha, body inches)', ARRAY['top','tee','shirt','polo','sweater','knit','hoodie','sweatshirt','jacket','coat','outerwear','blazer','vest']::text[], $json$[{"size":"XXS","measurements":{"neck":"13-13.5","chest":"32-34","sleeve":"30.5"}},{"size":"XS","measurements":{"neck":"13.5-14","chest":"35-36","sleeve":"31.5"}},{"size":"S","measurements":{"neck":"14.5-15","chest":"37-39","sleeve":"32.5"}},{"size":"M","measurements":{"neck":"15-15.5","chest":"40-42","sleeve":"33.5"}},{"size":"L","measurements":{"neck":"15.5-16","chest":"43-45","sleeve":"34.5"}},{"size":"XL","measurements":{"neck":"16.5-17","chest":"46-48","sleeve":"35.5"}},{"size":"XXL","measurements":{"neck":"17-18","chest":"49-51","sleeve":"36.5"}},{"size":"XXXL","measurements":{"neck":"18-19","chest":"52-54","sleeve":"37.5"}}]$json$::jsonb, 'AE''s men''s tops chart; its jackets are sized off the same one. The published table also carries M/L/XL Tall rows with the SAME neck and chest and about an inch more sleeve — left out here so the run stays a sequence a size check can count steps along.', 'https://www.ae.com/us/en/content/help/men-size-chart', 0.85, false, 'migration:00781'),
  ('bananarepublic', 'Banana Republic', ARRAY['banana republic','bananarepublic']::text[], 'Women', 'Bottoms, dresses & outerwear (alpha/numeric, body inches)', ARRAY['bottom','pant','trouser','jean','denim','short','skirt','chino','legging','dress','romper','jumpsuit','jacket','coat','outerwear','blazer','vest']::text[], $json$[{"size":"XXS / 000","measurements":{"bust":"30.5","waist":"24","hip":"33.5","sleeve":"30"}},{"size":"XXS / 00","measurements":{"bust":"31.5","waist":"25","hip":"34.5","sleeve":"30"}},{"size":"XS / 0","measurements":{"bust":"32.5","waist":"26","hip":"35.5","sleeve":"31"}},{"size":"XS / 2","measurements":{"bust":"33.5","waist":"27","hip":"36.5","sleeve":"31"}},{"size":"S / 4","measurements":{"bust":"34.5","waist":"28","hip":"37.5","sleeve":"31.5"}},{"size":"S / 6","measurements":{"bust":"35.5","waist":"29","hip":"38.5","sleeve":"31.5"}},{"size":"M / 8","measurements":{"bust":"36.5","waist":"30","hip":"39.5","sleeve":"32"}},{"size":"M / 10","measurements":{"bust":"37.5","waist":"31","hip":"40.5","sleeve":"32"}},{"size":"L / 12","measurements":{"bust":"39","waist":"32.5","hip":"42","sleeve":"32.5"}},{"size":"L / 14","measurements":{"bust":"40.5","waist":"34","hip":"43.5","sleeve":"32.5"}},{"size":"XL / 16","measurements":{"bust":"42.5","waist":"36","hip":"45.5","sleeve":"33.5"}},{"size":"XL / 18","measurements":{"bust":"44.5","waist":"38","hip":"47.5","sleeve":"33.5"}},{"size":"XXL / 20","measurements":{"bust":"47.5","waist":"41","hip":"50.5","sleeve":"34"}}]$json$::jsonb, 'BR shows this same women''s body chart behind every category in its own picker (tops, bottoms, blazers & outerwear, dresses, skirts), so one set of numbers answers for all of them. Body measurements, not flat. Petite and Tall are separate published charts and are not folded in here.', 'https://bananarepublic.gap.com/browse/info.do?cid=35404', 0.85, false, 'migration:00781'),
  ('bananarepublic', 'Banana Republic', ARRAY['banana republic','bananarepublic']::text[], 'Men', 'Bottoms & outerwear (alpha, body inches)', ARRAY['bottom','pant','trouser','chino','short','jean','denim','jacket','coat','outerwear','blazer','vest']::text[], $json$[{"size":"XXS","measurements":{"waist":"25-26","chest":"32-33","neck":"13-13.5","sleeve":"31"}},{"size":"XS","measurements":{"waist":"27-28","chest":"34-35","neck":"13-13.5","sleeve":"32"}},{"size":"S","measurements":{"waist":"29-31","chest":"36-37","neck":"14-14.5","sleeve":"33"}},{"size":"M","measurements":{"waist":"32-34","chest":"38-40","neck":"15-15.5","sleeve":"34"}},{"size":"L","measurements":{"waist":"36-38","chest":"41-44","neck":"16-16.5","sleeve":"35"}},{"size":"XL","measurements":{"waist":"40-42","chest":"45-48","neck":"17-17.5","sleeve":"36"}},{"size":"XXL","measurements":{"waist":"44-46","chest":"49-52","neck":"18-18.5","sleeve":"37"}}]$json$::jsonb, 'BR''s men''s regular chart, shown unchanged behind shirts, bottoms, blazers and outerwear alike. Body measurements. The belt column is a belt SIZE, not a body measurement, and is left out. Tall is a separate chart.', 'https://bananarepublic.gap.com/browse/info.do?cid=35404', 0.85, false, 'migration:00781'),
  ('canadagoose', 'Canada Goose', ARRAY['canada goose','canadagoose']::text[], 'Women', 'Tops & bottoms (Standard fit, body inches)', ARRAY['top','tee','shirt','sweater','knit','hoodie','sweatshirt','fleece','bottom','pant','trouser','legging','short','jogger','sweatpant']::text[], $json$[{"size":"3XS","measurements":{"bust":"27.75-29","waist":"22-22.75","hip":"31.75-33","sleeve":"28.25-29.5"}},{"size":"2XS","measurements":{"bust":"29.75-31","waist":"24-25","hip":"33.75-35","sleeve":"29-29.5"}},{"size":"XS","measurements":{"bust":"31.75-33","waist":"25.75-27","hip":"35.75-37","sleeve":"29.75-30.25"}},{"size":"S","measurements":{"bust":"33.75-35","waist":"27.75-29","hip":"38-38.75","sleeve":"30.5-31"}},{"size":"M","measurements":{"bust":"35.75-37","waist":"29.75-31","hip":"40-40.75","sleeve":"31.25-31.75"}},{"size":"L","measurements":{"bust":"38.5-40","waist":"32.5-33.75","hip":"42.5-44","sleeve":"31.75-32.25"}},{"size":"XL","measurements":{"bust":"41.25-42.75","waist":"35.25-37","hip":"45.5-46.75","sleeve":"32.5-33"}},{"size":"2XL","measurements":{"bust":"44.75-46.75","waist":"38.75-40.75","hip":"48.75-51","sleeve":"33.25-33.75"}},{"size":"3XL","measurements":{"bust":"48.75-51","waist":"42.75-44.75","hip":"53-55","sleeve":"34.25-34.5"}}]$json$::jsonb, 'Canada Goose''s Women''s STANDARD chart, which is the brand''s apparel chart rather than an outerwear one. BODY measurements — on the parkas the existing outerwear rows cover, down loft puts the flat chest well above these numbers. Fusion Fit is a separate published chart, not this one.', 'https://www.canadagoose.com/us/en/customer-service/support/sizing-charts-sizefit.html', 0.85, false, 'migration:00781'),
  ('canadagoose', 'Canada Goose', ARRAY['canada goose','canadagoose']::text[], 'Men', 'Tops & bottoms (Standard fit, body inches)', ARRAY['top','tee','shirt','sweater','knit','hoodie','sweatshirt','fleece','bottom','pant','trouser','short','jogger','sweatpant']::text[], $json$[{"size":"3XS","measurements":{"chest":"29.75-31","waist":"22.75-24","hip":"29.75-31","sleeve":"31.75-33"}},{"size":"2XS","measurements":{"chest":"33-33.75","waist":"25.75-27","hip":"33-33.75","sleeve":"32.25-32.5"}},{"size":"XS","measurements":{"chest":"35-35.75","waist":"27.75-29","hip":"35-35.75","sleeve":"33-34.25"}},{"size":"S","measurements":{"chest":"37-38","waist":"29.75-31","hip":"37-38","sleeve":"33.75-34.25"}},{"size":"M","measurements":{"chest":"38.75-40","waist":"31.75-33","hip":"38.75-40","sleeve":"34.5-35"}},{"size":"L","measurements":{"chest":"41.25-42.75","waist":"34.5-35.75","hip":"41.25-42.75","sleeve":"35.25-35.75"}},{"size":"XL","measurements":{"chest":"44.25-46","waist":"37.25-38.75","hip":"44.25-46","sleeve":"35.75-36.5"}},{"size":"2XL","measurements":{"chest":"48-50","waist":"40.75-42.75","hip":"48-50","sleeve":"36.5-37.25"}},{"size":"3XL","measurements":{"chest":"51.75-53.75","waist":"44.75-46.75","hip":"51.75-53.75","sleeve":"37.75-38"}}]$json$::jsonb, 'Canada Goose''s Men''s STANDARD chart — the brand''s apparel chart, not an outerwear one. BODY measurements. Chest and hip are published as the same figures on this chart; that is what the brand prints, not a transcription slip. Fusion Fit is separate.', 'https://www.canadagoose.com/us/en/customer-service/support/sizing-charts-sizefit.html', 0.85, false, 'migration:00781'),
  ('champion', 'Champion', ARRAY['champion']::text[], 'Men', 'Bottoms (alpha, body inches)', ARRAY['bottom','pant','short','jogger','sweatpant','trouser','legging','tight']::text[], $json$[{"size":"XS","measurements":{"waist":"28-30","hip":"34-36"}},{"size":"S","measurements":{"waist":"30-32","hip":"36-38"}},{"size":"M","measurements":{"waist":"32-35","hip":"38-41"}},{"size":"L","measurements":{"waist":"35-39","hip":"41-45"}},{"size":"XL","measurements":{"waist":"39-44","hip":"45-48"}},{"size":"2XL","measurements":{"waist":"44-48","hip":"48-52"}}]$json$::jsonb, 'Champion''s published men''s bottoms chart. Body measurements, not flat.', 'https://www.champion.com/pages/mens-clothing-size-guide', 0.85, false, 'migration:00781'),
